# Console strings for the complete first-party Korean and English bundles. Run
# `python3 scripts/strings.py` to regenerate locales/ui/{ko,en}.json. Additional locale JSON files
# are preserved, merged over English at runtime, and validated by scripts/i18n-check.mjs.
import json, os

S = {}


def add(prefix, pairs):
    for k, v in pairs.items():
        key = f"{prefix}.{k}" if prefix else k
        # a key defined twice with different text silently loses one of them: edit the first instead
        if key in S and S[key] != v:
            raise SystemExit(f"strings.py: {key} is defined twice with different text")
        S[key] = v


