out = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", "..", "..", "..", "..", "locales", "ui"))
for i, lang in enumerate(["ko", "en"]):
    data = {k: v[i] for k, v in sorted(S.items())}
    with open(os.path.join(out, f"{lang}.json"), "w", encoding="utf-8", newline=chr(10)) as f:  # LF on Windows too
        json.dump(data, f, ensure_ascii=False, indent=2)
        f.write("\n")
print(len(S), "strings")
